--
-- Table structure for table `orders_items`
--

DROP TABLE IF EXISTS `orders_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `OrderID` bigint(20) unsigned NOT NULL,
  `company_id` bigint(20) unsigned DEFAULT NULL,
  `StockItem` bigint(20) unsigned NOT NULL DEFAULT 0,
  `PackageTypeID` bigint(20) unsigned DEFAULT NULL,
  `discount_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Quantity` bigint(20) unsigned NOT NULL,
  `discount` decimal(15,2) DEFAULT NULL,
  `discount_val` decimal(15,2) unsigned DEFAULT NULL,
  `UnitPrice` bigint(20) NOT NULL DEFAULT 0,
  `ContractDiscount` tinyint(5) unsigned DEFAULT 0,
  `total` bigint(20) unsigned NOT NULL,
  `PickedQuantity` bigint(20) unsigned DEFAULT NULL,
  `PickingCompletedWhen` datetime DEFAULT NULL,
  `LastEditedBy` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `orders_items_lasteditedby_foreign` (`LastEditedBy`),
  KEY `orders_items_orderid_foreign` (`OrderID`),
  KEY `orders_items_packagetypeid_foreign` (`PackageTypeID`),
  KEY `orders_items_product_foreign` (`StockItem`),
  KEY `orders_items_company_id_foreign` (`company_id`),
  CONSTRAINT `orders_items_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_items_lasteditedby_foreign` FOREIGN KEY (`LastEditedBy`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `orders_items_orderid_foreign` FOREIGN KEY (`OrderID`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `orders_items_packagetypeid_foreign` FOREIGN KEY (`PackageTypeID`) REFERENCES `package_types` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `orders_items_product_foreign` FOREIGN KEY (`StockItem`) REFERENCES `products` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=282 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

